/**
 * TokenBucket sınıfı: Belirli kapasite ve doldurma hızına sahip bir kova.
 * Jetonlar zamanla sürekli dolar, kesirli miktarları destekler.
 */

function validateNonNegativeFinite(name, value) {
    if (typeof value !== 'number' || Number.isNaN(value) || !isFinite(value) || value < 0) {
        throw new RangeError(name + ' pozitif sonlu sayı olmalıdır');
    }
}

function validatePositiveFinite(name, value) {
    if (typeof value !== 'number' || Number.isNaN(value) || !isFinite(value) || value <= 0) {
        throw new RangeError(name + ' pozitif sonlu sayı olmalıdır');
    }
}

class TokenBucket {
    /**
     * @param {Object} options
     * @param {number} options.capacity - Kova kapasitesi (pozitif sonlu sayı)
     * @param {number} options.refillPerSecond - Saniyedeki doldurma hızı (pozitif sonlu sayı)
     * @param {Function} options.now - Milisaniye döndüren fonksiyon (varsayılan: Date.now)
     */
    constructor({ capacity, refillPerSecond, now }) {
        now = now !== undefined ? now : Date.now;

        validatePositiveFinite('capacity', capacity);
        validateNonNegativeFinite('refillPerSecond', refillPerSecond);

        // Kova dolu başlar
        this._capacity = capacity;
        this._refillPerSecond = refillPerSecond;
        this._now = now;
        this._tokens = capacity;
        // Dolum hesabında o ana kadar görülen en büyük zaman referansı
        this._lastTime = now();
    }

    /**
     * n jetonu düşer ve yeterli varsa true döner, yoksa false.
     * @param {number} n - Alınacak jeton sayısı
     * @returns {boolean}
     */
    tryTake(n) {
        validatePositiveFinite('n', n);

        const now = this._now();
        const elapsed = now - this._lastTime;
        let tokensToAdd = elapsed * this._refillPerSecond;

        if (tokensToAdd > 0) {
            // Mevcut tokens + eklenen, capacity'yi geçmediği sürece
            const potentialTokens = this._tokens + tokensToAdd;
            const cappedTokens = Math.min(potentialTokens, this._capacity);
            this._tokens = cappedTokens;
            this._lastTime = now; // Zaman referansını güncelle
        }

        if (this._tokens >= n) {
            this._tokens -= n;
            return true;
        }
        return false;
    }

    /**
     * O anki jeton sayısını döner (kesirli olabilir).
     * @returns {number}
     */
    available() {
        const now = this._now();
        const elapsed = now - this._lastTime;
        let tokensToAdd = elapsed * this._refillPerSecond;

        if (tokensToAdd > 0) {
            const potentialTokens = this._tokens + tokensToAdd;
            return Math.min(potentialTokens, this._capacity);
        }
        return this._tokens;
    }

    /**
     * n jetonun kullanılabilir olmasına kaç ms kaldığını döner.
     * @param {number} n - Gerekli jeton sayısı
     * @returns {number} - Yukarı yuvarlanmış milisaniye veya Infinity
     */
    msUntil(n) {
        validatePositiveFinite('n', n);

        if (n > this._capacity) {
            return Infinity;
        }

        if (this._refillPerSecond === 0) {
            const now = this._now();
            return this._tokens >= n ? 0 : Infinity;
        }

        const now = this._now();
        const elapsed = now - this._lastTime;
        let tokensToAdd = elapsed * this._refillPerSecond;

        if (tokensToAdd > 0) {
            const potentialTokens = this._tokens + tokensToAdd;
            const currentTokens = Math.min(potentialTokens, this._capacity);
        } else {
            const currentTokens = this._tokens;
        }

        if (currentTokens >= n) {
            return 0;
        }

        const needed = n - currentTokens;
        const tokensPerMs = this._refillPerSecond / 1000;
        const msNeeded = Math.ceil(needed / tokensPerMs);

        return msNeeded;
    }
}

module.exports = { TokenBucket };

