/**
 * TokenBucket testleri
 */

const { TokenBucket } = require('./kova.js');

let pass = 0;
let fail = 0;

function assert(condition, name) {
    if (condition) {
        console.log('OK:', name);
        pass++;
    } else {
        console.log('FAIL:', name);
        fail++;
    }
}

console.log('=== Temel Testler ===');

// Test 1: Dolu başlar
const bucket1 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => 1000 });
assert(bucket1.available() === 10, 'Test 1: Dolu başlar');

// Test 2: tryTake başarılı
assert(bucket1.tryTake(8) === true, 'Test 2: tryTake(8) = true');
assert(bucket1.tryTake(2) === true, 'Test 3: tryTake(2) = true');
assert(bucket1.tryTake(1) === false, 'Test 4: tryTake(1) = false (yok)');

// Test 5: available doğru
assert(bucket1.available() === 0, 'Test 5: available = 0');

console.log('');
console.log('=== Kenar Durum Testleri ===');

// Test 6-9: Invalid capacity
try {
    new TokenBucket({ capacity: NaN, refillPerSecond: 2 });
    assert(false, 'Test 6: capacity=NaN');
} catch (e) {
    assert(e instanceof RangeError, 'Test 6: capacity=NaN -> RangeError');
}

try {
    new TokenBucket({ capacity: Infinity, refillPerSecond: 2 });
    assert(false, 'Test 7: capacity=Infinity');
} catch (e) {
    assert(e instanceof RangeError, 'Test 7: capacity=Infinity -> RangeError');
}

try {
    new TokenBucket({ capacity: 0, refillPerSecond: 2 });
    assert(false, 'Test 8: capacity=0');
} catch (e) {
    assert(e instanceof RangeError, 'Test 8: capacity=0 -> RangeError');
}

try {
    new TokenBucket({ capacity: -1, refillPerSecond: 2 });
    assert(false, 'Test 9: capacity=-1');
} catch (e) {
    assert(e instanceof RangeError, 'Test 9: capacity=-1 -> RangeError');
}

// Test 10-13: Invalid refillPerSecond
try {
    new TokenBucket({ capacity: 10, refillPerSecond: NaN });
    assert(false, 'Test 10: refillPerSecond=NaN');
} catch (e) {
    assert(e instanceof RangeError, 'Test 10: refillPerSecond=NaN -> RangeError');
}

try {
    new TokenBucket({ capacity: 10, refillPerSecond: Infinity });
    assert(false, 'Test 11: refillPerSecond=Infinity');
} catch (e) {
    assert(e instanceof RangeError, 'Test 11: refillPerSecond=Infinity -> RangeError');
}

try {
    new TokenBucket({ capacity: 10, refillPerSecond: 0 });
    assert(false, 'Test 12: refillPerSecond=0');
} catch (e) {
    assert(e instanceof RangeError, 'Test 12: refillPerSecond=0 -> RangeError');
}

try {
    new TokenBucket({ capacity: 10, refillPerSecond: -1 });
    assert(false, 'Test 13: refillPerSecond=-1');
} catch (e) {
    assert(e instanceof RangeError, 'Test 13: refillPerSecond=-1 -> RangeError');
}

// Test 14-18: Invalid tryTake/m
try {
    const b = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
    b.tryTake(NaN);
