/**
 * n jetonun kullanılabilir olmasına kaç ms kaldığını döner.
 * @param {number} n - Gerekli jeton sayısı
 * @returns {number} - Yukarı yuvarlanmış milisaniye veya Infinity
 */
msUntil(n) {
    validatePositiveFinite('n', n);

    if (n > this._capacity) {
        return Infinity;
    }

    if (this._refillPerSecond === 0) {
        return this._tokens >= n ? 0 : Infinity;
    }

    const now = this._now();
    // En büyük zaman referansını hesapla (zaman geri gitmemeli)
    const maxTime = Math.max(now, this._lastTime);
    const elapsed = maxTime - this._lastTime;
    let tokensToAdd = elapsed * this._refillPerSecond;

    const currentTokens = tokensToAdd > 0
        ? Math.min(this._tokens + tokensToAdd, this._capacity)
        : this._tokens;

    if (currentTokens >= n) {
        return 0;
    }

    const needed = n - currentTokens;
    const tokensPerMs = this._refillPerSecond / 1000;
    const msNeeded = Math.ceil(needed / tokensPerMs);

    return msNeeded;
}

